<?php require_once __DIR__.'/lib/inicio.php';exigir_sesion();require_once __DIR__.'/lib/PdfSimple.php';$c=obtener_caso((int)$_GET['id']);$p=new PdfSimple;$p->titulo('FICHA TÉCNICA DEL CASO DE ACTUALIZACIÓN');$p->linea('Folio: '.$c['folio'],13,true);$p->linea('Estado: '.etiqueta_estado($c['estado']).' | Resultado: '.($c['resultado_tecnico']?:'Pendiente'));$secciones=['I. IDENTIFICACIÓN'=>['Distrito'=>$c['numero_distrito'],'Demarcación'=>$c['nombre_demarcacion'],'UT'=>$c['clave_ut'].' '.$c['nombre_ut'],'Secciones C'=>$c['secciones_c'],'Secciones P'=>$c['secciones_p'],'Tipo de caso'=>$c['tipo_caso']?:'Pendiente'],'II. SOLICITUD'=>['Solicitante'=>$c['nombre_solicitante'],'Descripción'=>$c['descripcion_solicitud'],'Clasificación'=>$c['analisis_clasificacion']],'III. PLANEACIÓN'=>['Contenido'=>$c['planeacion']],'IV. CAMPO Y ENCUESTAS'=>['Campo'=>$c['trabajo_campo'],'Modelo'=>$c['modelo_encuesta'],'Aplicadas'=>$c['encuestas_aplicadas'],'A favor'=>$c['respuestas_favor'],'En contra'=>$c['respuestas_contra']],'V. ACTUALIZACIÓN EXTERNA'=>['Contenido'=>$c['actualizacion_externa']],'VI. PROPUESTA'=>['Contenido'=>$c['propuesta_distrital']],'VII. REVISIÓN TÉCNICA'=>['Revisión'=>$c['revision_tecnica'],'Resultado'=>$c['resultado_tecnico']],'VIII. CIERRE'=>['Contenido'=>$c['cierre_expediente']]];foreach($secciones as $titulo=>$valores){if($titulo==='V. ACTUALIZACIÓN EXTERNA'&&!requiere_actualizacion_externa($c['tipo_caso']))continue;$p->linea();$p->linea($titulo,12,true);foreach($valores as $k=>$v)$p->linea($k.': '.($v?:'Pendiente'));}$p->descargar($c['folio'].'_ficha_tecnica.pdf');